import assert from 'node:assert/strict';

export async function runMotionStyleSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),bg:sec().bg}));
  async function frame(){await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd[data-motion-text]'));return (await page.$('.nw-motion-dialog iframe')).contentFrame();}
  async function select(selector){const f=await frame(),n=await f.$(selector),r=await n.boundingBox();await page.mouse.click(r.x+r.width/2,r.y+r.height/2);return n.evaluate(n=>n.dataset.id);}
  async function change(selector,value){await page.$eval(selector,(n,v)=>{n.value=v;n.dispatchEvent(new Event('change',{bubbles:true}));},value);}
  async function styles(){return page.evaluate(()=>{const d=document.querySelector('.nw-motion-dialog iframe').contentDocument,n=d.querySelector('.hd'),s=d.defaultView.getComputedStyle(n);return {color:s.color,weight:s.fontWeight,size:parseFloat(s.fontSize),align:s.textAlign,bg:d.defaultView.getComputedStyle(d.querySelector('.sc')).backgroundColor,inline:n.style.fontSize};});}
  await page.click('.tb-left [data-motion-open]');await frame();assert.equal(await page.$eval('[data-motion-text-style-panel]',n=>n.hidden),true);
  const id=await select('.hd');assert.equal(await page.$eval('[data-motion-text-style="customSize"]',n=>n.value),'34');assert.equal(await page.$eval('[data-motion-text-style="weight"]',n=>n.value),'700');
  await change('[data-motion-text-style="customSize"]','48');await change('[data-motion-text-style="weight"]','400');await change('[data-motion-text-style="textAlign"]','left');await change('[data-motion-text-style="color"]','#e36a45');await change('[data-motion-background]','#e8eef3');
  await page.waitForFunction(()=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument,n=d?.querySelector('.hd');return n?.style.fontSize.includes('48px')&&d.defaultView.getComputedStyle(n).color==='rgb(227, 106, 69)'&&d.defaultView.getComputedStyle(d.querySelector('.sc')).backgroundColor==='rgb(232, 238, 243)';});
  const rendered=await styles();assert.equal(rendered.weight,'400');assert.equal(rendered.align,'left');assert.ok(rendered.size>=29&&rendered.size<=48,'Preview uses base size even inside a narrow iframe');
  await select('.im-hov');assert.equal(await page.$eval('[data-motion-text-style-panel]',n=>n.hidden),true);assert.equal(await page.$$eval('[data-motion-text-style]',ns=>ns.every(n=>n.disabled)),true);await select('.hd');
  await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');assert.equal(await page.$eval('[data-motion-background]',n=>n.value),'#10121b');
  await page.click('[data-motion-template="iso-focus"]');await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"].nw-motion-selected')?.style.fontSize.includes('48px'),{},id);assert.equal(await page.$eval('[data-motion-text-style="color"]',n=>n.value),'#e36a45');assert.equal(await page.$eval('[data-motion-background]',n=>n.value),'#e8eef3');
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-insert-group]');
  const inserted=await page.evaluate(id=>({project:JSON.stringify(project),group:sec().elements.find(e=>e.nwMotionInstance),heading:sec().elements.find(e=>e.id===id),sceneBg:sec().bg}),id);
  assert.equal(inserted.group.bg,'#e8eef3');assert.equal(inserted.sceneBg,before.bg);assert.equal(inserted.heading.customSize,48);assert.equal(inserted.heading.weight,'400');assert.equal(inserted.heading.color,'#e36a45');assert.equal(inserted.heading.textAlign,'left');assert.equal(inserted.heading.mobile.customSize,25,'Authored mobile size remains intact');
  await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);await select('.hd');assert.equal(await page.$eval('[data-motion-text-style="customSize"]',n=>n.value),'48');await change('[data-motion-background]','#334455');await change('[data-motion-text-style="customSize"]','32');await change('[data-motion-text-style="weight"]','600');await change('[data-motion-text-style="textAlign"]','right');await change('[data-motion-text-style="color"]','#aabbcc');await page.click('[data-motion-save]');
  const saved=await page.evaluate(id=>({project:JSON.stringify(project),group:sec().elements.find(e=>e.nwMotionInstance),heading:sec().elements.find(e=>e.id===id),groups:sec().elements.filter(e=>e.nwMotionInstance).length}),id);
  assert.equal(saved.groups,1);assert.equal(saved.group.bg,'#334455');assert.deepEqual(saved.heading,{...inserted.heading,customSize:32,weight:'600',textAlign:'right',color:'#aabbcc'},'Only chosen text styles change');
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);await select('.hd');await change('[data-motion-text-style="customSize"]','0');await change('[data-motion-text-style="weight"]','');await change('[data-motion-background]','#ffffff');await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='style-export';f.style.width='1000px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});
  await page.waitForFunction(id=>document.querySelector('#style-export')?.contentDocument?.querySelector('[data-id="'+id+'"]'),{},id);
  const exported=await page.evaluate(({id,gid})=>{const f=document.querySelector('#style-export'),d=f.contentDocument,n=d.querySelector('[data-id="'+id+'"]'),s=f.contentWindow.getComputedStyle(n);return {color:s.color,weight:s.fontWeight,size:s.fontSize,align:s.textAlign,bg:f.contentWindow.getComputedStyle(d.querySelector('[data-id="'+gid+'"]')).backgroundColor};},{id,gid:inserted.group.id});
  assert.deepEqual(exported,{color:'rgb(170, 187, 204)',weight:'600',size:'32px',align:'right',bg:'rgb(51, 68, 85)'});
  console.log('Estilos Motion Lab: selección contextual, tamaño/color/peso/alineación visibles, fondo, borradores, móvil preservado, inserción/guardado misma instancia, cancelar, historial y exportación OK');
 }finally{
  await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#style-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
